def max_distance(position, m):
    position.sort()

    def balls_placed(d):
        count = 1
        last = position[0]
        for p in position[1:]:
            if p - last >= d:
                count += 1
                last = p
        return count

    lo, hi = 1, position[-1] - position[0]

    while lo < hi:
        mid = (lo + hi + 1) // 2
        if balls_placed(mid) >= m:
            lo = mid
        else:
            hi = mid - 1

    return lo

